CREATE TABLE IF NOT EXISTS public.attendance_records ( id uuid DEFAULT gen_random_uuid() PRIMARY KEY, company_id uuid REFERENCES public.companies(id) ON DELETE CASCADE NOT NULL, route_id uuid REFERENCES public.routes(id) ON DELETE CASCADE NOT NULL, student_id uuid REFERENCES public.students(id) ON DELETE CASCADE NOT NULL, driver_id uuid REFERENCES public.users(id) ON DELETE SET NULL, date date NOT NULL DEFAULT CURRENT_DATE, status text CHECK (status IN ('present', 'absent', 'pending')) DEFAULT 'pending', created_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL, UNIQUE(route_id, student_id, date) );
